/* ------------------------------------------------------------------ sizes and styles */
const SIZES = {
  '1x1': { h: 173, w: 173, cols: 6, rows: 3, label: 'Small · 1 × 1' },
  '2x1': { h: 173, w: 356, cols: 12, rows: 3, label: 'Wide · 2 × 1' },
  '2x2': { h: 356, w: 356, cols: 12, rows: 6, label: 'Large · 2 × 2' }
};
const STYLES = {
  '1x1': [['minimal', 'Minimal', 'Large graphic only'], ['basic', 'Basic', 'Graphic, name and state'], ['detailed', 'Detailed', 'Name, large state and one more detail (the icon is a setting)'], ['detailed_no_icon', 'Detailed, no icon', 'Name first, large state, one more detail']],
  '2x1': [['basic', 'Basic', 'Graphic, name, state and buttons'], ['detailed', 'Detailed', 'Buttons, sliders, graphs and more detail']],
  '2x2': [['minimal', 'Minimal', 'Large graphic only'], ['basic', 'Basic', 'Graphic with buttons'], ['detailed', 'Detailed', 'The full design for the device']]
};
// 2 × 2 detailed without the icon, for types whose detailed card has an icon in its header
const NOICON2 = ['detailed_no_icon', 'Detailed, no icon', 'The full design with the name first and no icon'];
const stylesAll = (type, size) => (TYPES[type] && TYPES[type].onlyStyles && TYPES[type].onlyStyles[size]) || STYLES[size].concat(((TYPES[type] && TYPES[type].extraStyles) || {})[size] || []);
// the styles offered: "detailed, no icon" is no longer a style of its own (show_icon decides)
const stylesFor = (type, size) => stylesAll(type, size).filter((x) => x[0] !== 'detailed_no_icon');
// whether this type and size has a layout without the icon (then show_icon switches between the two)
// a style's name for the option tags (the no-icon style reads as Detailed; unknown styles as themselves)
const styleLabel = (type, size, style) => { const l = stylesAll(type, size).find((x) => x[0] === (style === 'detailed_no_icon' ? 'detailed' : style)); return l ? l[1] : cap(String(style || '')); };
const noIconOK = (type, size) => !!stylesAll(type, size).find((x) => x[0] === 'detailed_no_icon');
const styleFor = (size, style, type) => { if (style === 'detailed_no_icon') style = 'detailed'; const l = stylesFor(type, size); if (l.find((x) => x[0] === style)) return style; const d = STYLES[size][size === '2x1' ? 0 : 1][0]; return l.find((x) => x[0] === d) ? d : l[0][0]; };
const TAP = [
  ['flip', 'Flip to the buttons'], ['more-info', 'More info'], ['device', 'Go to the device page'],
  ['toggle', 'Toggle'], ['navigate', 'Navigate to a dashboard or page'], ['perform-action', 'Perform an action'], ['none', 'No action']
];
// the big minimal lock, alarm and vacuum tiles turn over to their buttons
const minFlip = (type, size, style) => size === '2x2' && ((style === 'minimal' && (type === 'lock' || type === 'alarm' || type === 'vacuum')) || (style === 'basic' && type === 'vacuum'));
