// the dial: a 270° gauge filling to the target, with a knob at the target and a mark at the room temperature on larger cards
function climDial(px, d, o, ds) {
  o = o || {};
  const col = d.col;
  const pt = (f, r) => { const th = (225 + Math.max(clamp(f, 0, 1) * 270, 1)) * Math.PI / 180; return [35 + r * Math.sin(th), 35 - r * Math.cos(th)]; };
  const [ex, ey] = pt(d.f, 28.5), deg = Math.max(clamp(d.f, 0, 1) * 270, 1);
  const track = 'M14.85 55.15A28.5 28.5 0 1 1 55.15 55.15';
  const fill = 'M14.85 55.15A28.5 28.5 0 ' + (deg > 180 ? 1 : 0) + ' 1 ' + ex.toFixed(2) + ' ' + ey.toFixed(2);
  const lay = (inner) => '<div style="position:absolute;left:0;top:0;width:' + px + 'px;height:' + px + 'px;filter:' + ds + '"><svg width="' + px + '" height="' + px + '" viewBox="0 0 70 70" fill="none" stroke-linecap="round" style="display:block">' + inner + '</svg></div>';
  let h = lay('<path d="' + track + '" stroke-width="13" style="stroke:var(--card-background-color)"/><path d="' + track + '" stroke-width="13" style="stroke:' + mix(col, 28, 'transparent') + '"/>');
  if (o.now && d.fNow != null) { const [nx, ny] = pt(d.fNow, 28.5); h += '<svg style="position:absolute;left:0;top:0" width="' + px + '" height="' + px + '" viewBox="0 0 70 70"><circle cx="' + nx.toFixed(2) + '" cy="' + ny.toFixed(2) + '" r="1.7" style="fill:' + mix('var(--primary-text-color)', 45, 'transparent') + '"/></svg>'; }
  if (d.on) h += lay('<path d="' + fill + '" stroke-width="8" style="stroke:' + col + '"/>');
  if (d.on && o.knob) h += lay('<circle cx="' + ex.toFixed(2) + '" cy="' + ey.toFixed(2) + '" r="5.6" style="fill:var(--card-background-color)"/>');
  if (o.centre) {
    const big = Math.round(px * (o.big || 0.22));
    h += '<div style="position:absolute;left:0;top:0;width:' + px + 'px;height:' + px + 'px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center">' +
      '<div style="white-space:nowrap;line-height:1;color:' + (d.on ? 'var(--primary-text-color)' : 'var(--secondary-text-color)') + '"><span style="font-size:' + (d.t.length > 4 ? Math.round(big * 0.62) : big) + 'px;font-weight:600;letter-spacing:-1px">' + esc(d.t) + '</span><span style="font-size:' + Math.round(big * 0.38) + 'px;font-weight:500;color:var(--secondary-text-color);margin-left:2px;vertical-align:top;position:relative;top:' + Math.round(big * 0.08) + 'px">' + esc(d.unit) + '</span></div>' +
      (o.centre === 'full' ? '<div style="font-size:' + Math.max(11, Math.round(px * 0.05)) + 'px;line-height:1.3;margin-top:' + Math.round(px * 0.025) + 'px;color:var(--secondary-text-color);white-space:nowrap">' + esc(d.sub) + '</div>' : '') + '</div>';
  }
  return '<div style="position:relative;flex:none;width:' + px + 'px;height:' + px + 'px;transform:translateY(' + Math.round(px * 0.06) + 'px)">' + h + '</div>';
}
// split system: the wall unit is the off shape; when running a lit vane sits inside its slot with its own shadow and air flows out below
function climSplit(px, d, ds) {
  const on = d.on, col = d.col, k = px / 96, G = 'var(--hamptons-color-15, var(--dw-p15))';
  const b = (l, t, w, hh, r, bg, extra) => '<div style="position:absolute;left:' + l + 'px;top:' + t + 'px;width:' + w + 'px;height:' + hh + 'px;border-radius:' + r + 'px;background:' + bg + ';' + (extra || '') + '"></div>';
  const air = on ? '<svg style="position:absolute;left:0;top:0;filter:' + ds + '" width="96" height="96" viewBox="0 0 96 96" fill="none" stroke-linecap="round" stroke-width="3.2">' +
    [30, 48, 66].map((x, i) => '<path d="M' + x + ' ' + (60 + (i === 1 ? 2 : 0)) + 'q4.5 4.5 0 9q-4.5 4.5 0 9" style="stroke:' + mix(col, i === 1 ? 85 : 60, 'transparent') + '"/>').join('') + '</svg>' : '';
  return '<div style="position:relative;flex:none;width:' + px + 'px;height:' + px + 'px"><div style="position:absolute;left:0;top:0;width:96px;height:96px;transform:scale(' + k.toFixed(3) + ');transform-origin:0 0">' +
    b(5, 18, 86, 36, 14, on ? mix(col, 20) : mix(G, 22), 'box-shadow:var(--dw-sh)') +
    b(12, 25, 48, 2.4, 2, mix(G, on ? 22 : 30)) + b(12, 30, 36, 2.4, 2, mix(G, on ? 22 : 30)) +
    b(76, 24, 7, 7, 4, on ? col : mix(G, 40), on ? 'box-shadow:var(--dw-sh)' : '') +
    b(12, 40, 72, 9, 5, mix(G, on ? 30 : 38), 'box-shadow:inset 0 1px 2px rgba(0,0,0,.08)') +
    (on ? b(14, 42, 68, 5, 3, col, 'box-shadow:var(--dw-sh)') : '') + air + '</div></div>';
}

