// is this sensor one of the weather station elements? (otherwise it is a plain number)
function isElement(hass, id) {
  const s = hass.states[id] || { attributes: {} }, A = s.attributes, dc = A.device_class || '', u = A.unit_of_measurement || '';
  const t = ((A.friendly_name || '') + ' ' + id).toLowerCase();
  return ['temperature', 'humidity', 'wind_speed', 'pressure', 'atmospheric_pressure', 'precipitation', 'precipitation_intensity', 'irradiance'].indexOf(dc) >= 0 ||
    /°c|°f|hpa|mbar|inhg|mm\/h|in\/h|w\/m/i.test(u) || /\buv\b|uv_index|wind|gust|rain|precip|solar|radiation|humid|temperature/.test(t);
}

