/* ---------- clock, timers and calendars ---------- */
// the time in a time zone (blank = this device): hours 0-23, minutes, and words for the day and date
function tzParts(d, tz) {
  const o = { hour: 'numeric', minute: '2-digit', hourCycle: 'h23', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' };
  if (tz) o.timeZone = tz;
  let p;
  try { p = new Intl.DateTimeFormat('en-AU', o).formatToParts(d); } catch (e) { delete o.timeZone; p = new Intl.DateTimeFormat('en-AU', o).formatToParts(d); }
  const g = (t) => (p.find((x) => x.type === t) || {}).value || '';
  return { h: +g('hour') % 24, m: +g('minute'), weekday: g('weekday'), day: +g('day'), month: g('month'), year: +g('year') };
}
const tzShort = (tz) => { try { const o = { timeZoneName: 'short' }; if (tz) o.timeZone = tz; return (new Intl.DateTimeFormat('en-AU', o).formatToParts(new Date()).find((x) => x.type === 'timeZoneName') || {}).value || ''; } catch (e) { return ''; } };
const hm = (h, m, h24) => (h24 ? String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') : ((h % 12) || 12) + ':' + String(m).padStart(2, '0'));
const ampm = (h) => (h < 12 ? 'am' : 'pm');
const isoWeek = (y, mo, d) => { const t = new Date(Date.UTC(y, mo, d)); const n = t.getUTCDay() || 7; t.setUTCDate(t.getUTCDate() + 4 - n); const y0 = new Date(Date.UTC(t.getUTCFullYear(), 0, 1)); return Math.ceil(((t - y0) / 86400000 + 1) / 7); };
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const PSEUDO_T = new Date().toISOString();
// a clock needs no entity: give it a stand-in state so the rest of the card works as usual
function withPseudo(hass, r) {
  if (!hass || ['clock', 'sun', 'moon', 'energy', 'alerts', 'health'].indexOf(r.type) < 0 || hass.states[r.main]) return hass;
  return Object.assign({}, hass, { states: Object.assign({}, hass.states, { [r.main]: { entity_id: r.main, state: 'ok', attributes: { friendly_name: '' }, last_changed: PSEUDO_T, last_updated: PSEUDO_T } }) });
}
const secsOf = (x) => { if (x == null || x === '') return 0; if (typeof x === 'number') return x; const p = String(x).split(':').map(Number); return p.length === 3 ? p[0] * 3600 + p[1] * 60 + p[2] : p.length === 2 ? p[0] * 60 + p[1] : +x || 0; };
const clockTxt = (s) => { s = Math.max(0, Math.round(s)); const h = Math.floor(s / 3600), mm = Math.floor((s % 3600) / 60), ss = s % 60; return (h ? h + ':' + String(mm).padStart(2, '0') : mm) + ':' + String(ss).padStart(2, '0'); };
const durWords = (s) => { const h = Math.floor(s / 3600), mm = Math.round((s % 3600) / 60); return h ? h + ' h' + (mm ? ' ' + mm + ' min' : '') : mm + ' min'; };
const hmsOf = (s) => { s = Math.max(0, Math.round(s)); return String(Math.floor(s / 3600)).padStart(2, '0') + ':' + String(Math.floor((s % 3600) / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };
// each calendar's colour: calendar_colors, else the primary colour for the first, else the palette in turn
const calColour = (cfg, id, i) => colourOf((cfg.calendar_colors || {})[id]) || (i === 0 && cfg.on_color ? colourOf(cfg.on_color) : null) || CAL_COLS[i % CAL_COLS.length];
const CAL_COLS = ['var(--garden, var(--dw-c-garden))', 'var(--hamptons-color-6, var(--dw-p6))', 'var(--hamptons-color-11, var(--dw-p11))', 'var(--hamptons-color-5, var(--dw-p5))', 'var(--hamptons-color-14, var(--dw-p14))'];
const tShort = (d) => d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }).replace(/\s?([AP])M/i, (x, a) => ' ' + a.toLowerCase() + 'm').replace(':00 ', ' ');

