  if (Array.isArray(v)) return v.map((x) => (x && typeof x === 'object' && !Array.isArray(x) ? ind + '- ' + toYaml(x, ind + '  ').replace(/^\s+/, '') : ind + '- ' + (x && typeof x === 'object' ? JSON.stringify(x) : sc(x)))).join('\n');
  return Object.keys(v).map((k) => { const x = v[k]; return x && typeof x === 'object' ? (Array.isArray(x) && x.every((y) => typeof y !== 'object' || y === null) && x.length <= 4 ? ind + k + ': ' + JSON.stringify(x) : ind + k + ':\n' + toYaml(x, ind + '  ')) : ind + k + ': ' + sc(x); }).join('\n');
