        const bars = (x0, dir, c) => [1, 2, 3].map((k) => { const x = x0 + dir * lw * k / 4; return '<line x1="' + x.toFixed(1) + '" y1="' + (33 - sk * k / 4).toFixed(1) + '" x2="' + x.toFixed(1) + '" y2="' + (77 + sk * k / 4).toFixed(1) + '"></line>'; }).join('');
