/* ------------------------------------------------------------------ styles */
const STYLE = DW_PAL_CSS + `
.pscroll::-webkit-scrollbar{display:none}
:host{display:block;height:100%}
ha-card{backdrop-filter:var(--dw-blur,none);-webkit-backdrop-filter:var(--dw-blur,none);display:block;position:relative;box-sizing:border-box;width:100%;height:auto;aspect-ratio:var(--dw-ar);overflow:hidden;border-radius:var(--dw-radius);box-shadow:var(--dw-card-sh);background:var(--dw-bg);border:var(--dw-border);
  color:var(--primary-text-color);cursor:pointer;-webkit-tap-highlight-color:transparent;user-select:none}
:host([grid]) ha-card{height:auto;aspect-ratio:var(--dw-ar)}
:host([grid][fit]) ha-card{height:100%;aspect-ratio:auto}
.tinted .stage{--card-background-color:var(--dw-tint)}
.stw{position:absolute;left:var(--dw-ox,0px);top:var(--dw-oy,0px)}
.stage{position:relative;zoom:var(--dw-s,1)}
.nozoom .stage{zoom:1;transform:scale(var(--dw-s,1));transform-origin:0 0}
.a{position:absolute}
.hero{position:absolute}
svg{overflow:visible}
.isoff .btn,.isoff .slider,.isoff .pill,.isoff .step{--c:var(--dw-off)!important}.isoff .fanrow .btn{--c:var(--fc)!important}.isoff .ltrow .btn,.isoff .ltrow .slider{--c:var(--lc)!important}
.isoff .strip,.isoff .bars,.isoff .ct{filter:grayscale(1)}
ha-card.alring{box-shadow:inset 0 0 0 3px var(--al),var(--dw-card-sh);background:linear-gradient(color-mix(in srgb,var(--al) 18%,transparent),color-mix(in srgb,var(--al) 18%,transparent)),var(--dw-bg)}
ha-card.flipout{transition:transform .17s ease-in;transform:perspective(900px) rotateY(90deg)}
ha-card.flipin{animation:dwflip .22s ease-out}
@keyframes dwflip{from{transform:perspective(900px) rotateY(-90deg)}to{transform:perspective(900px) rotateY(0)}}
.mq{display:inline-block;padding-right:2px;animation:dwmq var(--mqd,8s) linear infinite}
@keyframes dwmq{0%,18%{transform:translateX(0)}62%,80%{transform:translateX(var(--mq))}100%{transform:translateX(0)}}
@media (prefers-reduced-motion: reduce){.mq{animation:none}ha-card.flipin{animation:none}}
.chip{position:absolute;width:48px;height:48px;border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:var(--dw-sh)}
.chip ha-icon{--mdc-icon-size:28px;display:flex}
.chip.s{width:40px;height:40px}.chip.s ha-icon{--mdc-icon-size:22px}
.st{white-space:nowrap;flex:none}.st b{font-size:18px;font-weight:600;letter-spacing:-.3px}.st i{font-style:normal;font-size:12px;font-weight:500;color:var(--secondary-text-color);margin-left:3px}
.nm{font-size:14px;font-weight:600;line-height:18px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word}
.nm1{font-size:14px;font-weight:600;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sm{font-size:11px;line-height:15px;color:var(--secondary-text-color);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.row{display:flex;align-items:center;gap:8px}
.grow{flex:1;min-width:0}
.btn{flex:none;border:0;padding:0;margin:0;font:inherit;display:flex;align-items:center;justify-content:center;gap:5px;cursor:pointer;border-radius:999px;position:relative;
  background:color-mix(in srgb,var(--c) 30%,var(--card-background-color));color:color-mix(in srgb,var(--c) 60%,var(--primary-text-color));box-shadow:var(--dw-sh);font-size:12px;font-weight:600;white-space:nowrap}
/* on: the soft base keeps its shadow; a solid inner element sits 2px inside it with its own shadow */
.btn.on{color:var(--card-background-color)}
.btn.on::before{content:'';position:absolute;inset:2px;border-radius:inherit;background:var(--c);box-shadow:var(--dw-sh)}
.btn>*{position:relative}
.btn ha-icon{display:flex}
.step{position:absolute;border-radius:999px;box-shadow:var(--dw-sh);display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:5px 0;box-sizing:border-box;
  background:color-mix(in srgb,var(--c) 30%,var(--card-background-color))}
.step .v{font-size:13px;font-weight:600}
.pill{display:inline-flex;align-items:center;gap:4px;height:24px;padding:0 9px;border-radius:12px;font-size:11px;font-weight:600;white-space:nowrap;flex:none;
  background:color-mix(in srgb,var(--c) 22%,var(--card-background-color));color:color-mix(in srgb,var(--c) 55%,var(--primary-text-color))}
.pill ha-icon{--mdc-icon-size:14px;display:flex}
.rgrid .btn{width:100%;min-width:0;padding:0 8px}.rgrid .btn span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.slider{position:relative;border-radius:999px;box-shadow:var(--dw-sh);background:color-mix(in srgb,var(--c) 22%,var(--card-background-color));touch-action:none;cursor:pointer;flex:none}
/* the fill sits 2px inside the track with its own shadow, never narrower than a round knob */
.slider>.f{position:absolute;left:2px;top:2px;bottom:2px;border-radius:999px;background:var(--c);box-shadow:var(--dw-sh);width:max(calc(var(--h) - 4px), calc((100% - 4px) * var(--f)))}
.slider>.f.z{display:none}
.slider>ha-icon{position:absolute;left:calc(2px + (var(--h) - 4px) / 2);top:50%;transform:translate(-50%,-50%);--mdc-icon-size:calc(var(--h) * 0.58);display:flex;color:var(--card-background-color)}
.slider>.f.z~ha-icon{color:color-mix(in srgb,var(--c) 60%,var(--primary-text-color))}
.ct{position:relative;border-radius:999px;box-shadow:var(--dw-sh);touch-action:none;cursor:pointer;flex:none}
.ct>.k{position:absolute;top:2px;bottom:2px;aspect-ratio:1;border-radius:50%;background:var(--card-background-color);box-shadow:var(--dw-sh);left:calc(2px + (100% - var(--h)) * var(--f))}
.strip{display:flex;gap:2px}.strip>span{flex:1;border-radius:3px}
.bar{height:6px;border-radius:3px;position:relative;box-shadow:var(--dw-sh);background:color-mix(in srgb,var(--c) 25%,var(--card-background-color))}
.bar>.f{position:absolute;left:0;top:0;bottom:0;border-radius:3px;background:var(--c)}
.art{position:absolute;border-radius:16px;overflow:hidden;box-shadow:var(--dw-sh);display:flex;align-items:center;justify-content:center;
  background:radial-gradient(circle at 30% 30%, color-mix(in srgb,var(--c) 55%,#fff), transparent 60%),linear-gradient(135deg,var(--hamptons-color-13, var(--dw-p13)),var(--c))}
.art.off{background:color-mix(in srgb,var(--dw-off) 22%,var(--card-background-color))}
.art.grad,.grad{background:var(--dw-grad);background-size:260% 260%;background-position:20% 20%}
.art.hero{background:color-mix(in srgb,var(--c) 12%,var(--card-background-color))}
.idle .grad{filter:grayscale(.75) opacity(.7)}
.gplay [role=img]{background:var(--dw-grad) !important;background-size:260% 260% !important}
.gplay .grad,.gplay [role=img]{animation:dwDrift 11s ease-in-out infinite alternate}
@keyframes dwDrift{0%{background-position:0% 0%;filter:saturate(1)}25%{background-position:100% 25%}50%{background-position:55% 100%;filter:saturate(1.15)}75%{background-position:0% 70%}100%{background-position:100% 100%;filter:saturate(1)}}
@media (prefers-reduced-motion: reduce){.gplay .grad,.gplay [role=img]{animation:none}}
.art img{width:100%;height:100%;object-fit:cover;display:block}
img.aimg{transition:opacity .35s}img.aimg.wait{opacity:0}
.favt{border:0;background:none;padding:0;margin:0;cursor:pointer;color:var(--primary-text-color);font:inherit;display:flex;flex-direction:column;align-items:center;gap:5px;flex:none}
.favt .th{border-radius:12px;box-shadow:var(--dw-sh);background-color:color-mix(in srgb,var(--dw-on) 22%,var(--card-background-color));background-size:cover;background-position:center;display:flex;align-items:center;justify-content:center;color:color-mix(in srgb,var(--dw-on) 70%,var(--card-background-color))}
.favt .cap{font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center}
.favt:active .th{transform:scale(.96)}
.art ha-icon{color:color-mix(in srgb,var(--dw-off) 70%,var(--card-background-color))}
`;

