      m.gfx = (px, o) => (o && o.t != null ? climDial(px, Object.assign({}, d, { t: o.t, unit: o.unit, sub: o.sub }), o, ds) : r.sub === 'split' ? climSplit(px, d, ds) : r.sub === 'heater' ? '<div style="position:relative;flex:none;width:' + px + 'px;height:' + px + 'px">' + flame.centred(Math.round(px * 0.92), '50%') + '</div>' : climDial(px, d, o, ds));
