    if (AIR_TYPES.indexOf(m.type) >= 0) return this._airSmall(m);
    if (m.type === 'alerts') return this._ntSmall(m);
    if (m.type === 'health') return this._hlSmall(m);
    if (m.type === 'numin') return this._nuSmall(m);
    if (m.type === 'car' || m.type === 'cars') return this._carSmall(m.type === 'cars' ? Object.assign({}, m, { car: (m.items || [])[0], style: 'basic' }) : m) + (m.type === 'cars' ? this._at(0, 150, '<div class="sm" style="width:173px;text-align:center">' + esc(m.val + ' ' + m.unit) + '</div>') : '');
    if (PW_TYPES.indexOf(m.type) >= 0) return this._pwSmall(m);
    if (m.type === 'graph') return this._grSmall(m);
    if (m.type === 'graphs') return this._gsSmall(m);
    if (m.type === 'action') return this._acSmall(m);
    if (m.type === 'actions') return this._asSmall(m);
    if (m.type === 'group') return this._gSmall(m);
    if (m.type === 'timers') return this._tsSmall(m);
