  _evGo(m, size, iconSize) { return m.canGo && this._sh('controls') ? this._btn('pw:go', m.st === 'charging' ? 'mdi:pause' : 'mdi:play', size, m.st === 'charging', '', m.st === 'charging' ? m.onC : m.offC, iconSize) : ''; }
  _evAmps(m, size) { return m.cuE && this._sh('controls') && m.amps != null ? this._row(this._btn('pw:amp:down', 'mdi:minus', size, false, '', m.onC) + '<div style="width:40px;text-align:center;font-weight:600;font-size:14px">' + Math.round(m.amps) + ' A</div>' + this._btn('pw:amp:up', 'mdi:plus', size, false, '', m.onC), 4) : ''; }
