      exercise: f('exercise_entity', (e, n) => /exercise|active (minutes|time)|activity (minutes|time)|move minutes|very active/.test(n)),
      stand: f('stand_entity', (e, n) => /stand/.test(n)),
      sleep: f('sleep_entity', (e, n) => /sleep/.test(n) && /duration|time|asleep|total|^.*sleep$/.test(n) && !/deep|rem|light|core|awake|score|start|end/.test(n)),
