      spo2: f('spo2_entity', (e, n) => /spo2|oxygen|blood oxygen/.test(n)), hrv: f('hrv_entity', (e, n) => /hrv|variability/.test(n)), weight: f('weight_entity', (e) => dc(e) === 'weight'), vo2: f('vo2_entity', (e, n) => /vo2|vo₂/.test(n)), distance: f('distance_entity', (e, n) => dc(e) === 'distance' && /walk|distance|run/.test(n))
