/* ------------------------------------------------------------------ history timescale for graphs */
const HISTORY_OPTS = [['1', '1 hour'], ['3', '3 hours'], ['6', '6 hours'], ['12', '12 hours'], ['24', '24 hours'], ['48', '2 days'], ['168', '7 days'], ['today', 'Today (since midnight)']];
// does this card show history? (graphs, strips, or counts over the window)
function graphShown(r, cfg) {
  const det = r.style === 'detailed' || r.style === 'detailed_no_icon', g = cfg.show_graph !== false;
  if (r.type === 'graph') return ['donut', 'pie', 'bars'].indexOf(r.sub) < 0;
  if (r.type === 'light') return r.size !== '1x1' && det && g;
  if (r.type === 'element' || r.type === 'number') return r.size === '1x1' || (det && g);
  if (r.type === 'binary') return r.style !== 'minimal' || r.size === '1x1';
  if (r.type === 'tracker') return r.size !== '1x1' && det;
  if (r.type === 'cover') return r.size === '2x2' && det;
  if (r.type === 'climate') return (r.size === '2x1' && r.style === 'detailed' && g) || (r.size === '2x2' && det && (cfg.bottom || 'graph') === 'graph');
  return false;
}

